"use client"

import { useState } from "react"
import Link from "next/link"
import { Leaf, Menu, X } from "lucide-react"

export default function Navigation() {
  const [isOpen, setIsOpen] = useState(false)

  const links = [
    { label: "Home", href: "/" },
    { label: "Products", href: "/products" },
    { label: "About", href: "/about" },
    { label: "Contact", href: "/contact" },
  ]

  return (
    <nav className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b-2 border-border">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center py-5">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2 group">
            <div className="w-12 h-12 bg-primary rounded-xl flex items-center justify-center transition-smooth group-hover:scale-110 group-hover:shadow-lg shadow-md">
              <Leaf className="text-primary-foreground" size={24} />
            </div>
            <span className="font-bold text-2xl text-primary hidden sm:inline">Claspuro</span>
          </Link>

          {/* Desktop Menu */}
          <div className="hidden md:flex gap-12">
            {links.map((link) => (
              <Link
                key={link.label}
                href={link.href}
                className="text-foreground hover:text-primary transition-smooth text-base font-semibold hover:underline underline-offset-4"
              >
                {link.label}
              </Link>
            ))}
          </div>

          {/* CTA Button */}
          <button className="hidden md:block px-8 py-3 bg-primary text-primary-foreground font-bold rounded-xl hover:shadow-lg transition-smooth hover:scale-105 text-base">
            Order Now
          </button>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden p-2 hover:bg-muted rounded-lg transition-smooth"
          >
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isOpen && (
          <div className="md:hidden pb-6 space-y-3 animate-fade-in-up">
            {links.map((link) => (
              <Link
                key={link.label}
                href={link.href}
                className="block px-4 py-3 text-foreground hover:bg-primary/10 rounded-lg transition-smooth font-semibold"
                onClick={() => setIsOpen(false)}
              >
                {link.label}
              </Link>
            ))}
            <button className="w-full px-4 py-3 bg-primary text-primary-foreground font-bold rounded-lg hover:shadow-lg transition-smooth">
              Order Now
            </button>
          </div>
        )}
      </div>
    </nav>
  )
}
